//! The menu bar, built from the menu table (menu_table.rs, generated by tools/menus/menus_to_rust.py). Items keep
//! their command ids, except the seven clipboard and undo items, which use the wxWidgets standard ids so the
//! native text control carries them out as every program on the system does.

use std::collections::HashMap;

use wxdragon::prelude::*;
use wxdragon_sys as ffi;

use crate::menu_table::MENU_BAR;

pub enum Kind {
    Normal,
    Check,
    Radio,
}

pub enum Entry {
    /// Command id, label (with the shortcut after a tab), kind.
    Item(i32, &'static str, Kind),
    Separator,
    Menu(&'static str, &'static [Entry]),
}

/// The Edit menu ids and the wxWidgets standard ids that stand for them.
const STANDARD: &[(i32, i64)] = &[
    (1201, ffi::WXD_ID_UNDO),
    (1202, ffi::WXD_ID_REDO),
    (1203, ffi::WXD_ID_CUT),
    (1204, ffi::WXD_ID_COPY),
    (1205, ffi::WXD_ID_PASTE),
    (1206, ffi::WXD_ID_CLEAR),
    (1207, ffi::WXD_ID_SELECTALL),
];

/// The id a command has in the menu bar.
pub fn menu_id(command: i32) -> i32 {
    STANDARD.iter().find(|(d, _)| *d == command).map_or(command, |(_, w)| *w as i32)
}

/// The command a menu id stands for.
pub fn command_id(menu: i32) -> i32 {
    STANDARD.iter().find(|(_, w)| *w as i32 == menu).map_or(menu, |(d, _)| *d)
}

/// The first id of the open-document items at the end of the View menu (above the wxWidgets standard ids).
pub const DOCUMENT_BASE: i32 = 6100;

pub struct Menus {
    pub items: HashMap<i32, MenuItem>,
    pub view: Menu,
    pub documents: Vec<i32>,
}

impl Menus {
    /// Sets a check mark (command id).
    pub fn check(&self, command: i32, on: bool) {
        if let Some(item) = self.items.get(&menu_id(command)) {
            item.check(on);
        }
    }

    pub fn is_checked(&self, command: i32) -> bool {
        self.items.get(&menu_id(command)).is_some_and(|i| i.is_checked())
    }

    /// The open documents at the end of the View menu, numbered, the active one checked.
    pub fn set_documents(&mut self, names: &[String], active: Option<usize>) {
        for id in self.documents.drain(..) {
            self.view.remove(id);
        }
        if !names.is_empty() && self.view.get_item_count() > 0 {
            // A separator divides the list from the View commands.
            let sep = DOCUMENT_BASE - 1;
            if self.view.find_item(sep).is_none() {
                self.view.append(sep, "-", "", ItemKind::Separator);
            }
        }
        for (i, name) in names.iter().enumerate() {
            let id = DOCUMENT_BASE + i as i32;
            let label = if i < 9 { format!("&{} {}", i + 1, name) } else { name.replace('&', "&&") };
            if let Some(item) = self.view.append(id, &label, "", ItemKind::Check) {
                item.check(Some(i) == active);
            }
            self.documents.push(id);
        }
    }
}

fn fill(menu: &Menu, entries: &[Entry], items: &mut HashMap<i32, MenuItem>) {
    for entry in entries {
        match entry {
            Entry::Item(id, label, kind) => {
                let kind = match kind {
                    Kind::Normal => ItemKind::Normal,
                    Kind::Check => ItemKind::Check,
                    Kind::Radio => ItemKind::Radio,
                };
                let id = menu_id(*id);
                if let Some(item) = menu.append(id, label, "", kind) {
                    items.insert(id, item);
                }
            }
            Entry::Separator => menu.append_separator(),
            Entry::Menu(label, sub) => {
                let submenu = Menu::builder().build();
                fill(&submenu, sub, items);
                menu.append_submenu(submenu, label, "");
            }
        }
    }
}

/// Builds the menu bar and puts it on the main window.
pub fn install(frame: &MDIParentFrame) -> Menus {
    let mut items = HashMap::new();
    let mut builder = MenuBar::builder();
    for (label, entries) in MENU_BAR {
        let menu = Menu::builder().build();
        fill(&menu, entries, &mut items);
        builder = builder.append(menu, label);
    }
    let bar = builder.build();
    let view_index = MENU_BAR.iter().position(|(l, _)| *l == "&View").unwrap_or(2);
    let view = bar.get_menu(view_index).expect("View menu");
    frame.set_menu_bar(bar);
    Menus { items, view, documents: Vec::new() }
}
